import json, pathlib
import pycountry, plotly.express as px
from countryinfo import CountryInfo
P=pathlib.Path(__file__).parent
# Countries and continents from countryinfo reference data; coordinates are approximate geographic locations.
ci=CountryInfo().all()
meta={}
for slug,record in ci.items():
    iso=record.get('ISO',{}).get('alpha3','')
    if not iso or len(iso)!=3:continue
    ll=record.get('latlng',[])
    region=record.get('region','')
    if region=='Americas':
        # CountryInfo often includes subregion; use it to split North and South.
        sub=record.get('subregion','')
        region='South America' if 'South America' in sub else 'North America'
    if region in ['Australia','Australia and New Zealand']:region='Oceania'
    meta[iso]={'name':record.get('name',slug.title()),'lat':ll[0] if len(ll)>1 else None,'lon':ll[1] if len(ll)>1 else None,'continent':region}
for row in px.data.gapminder().drop_duplicates('iso_alpha').itertuples():
    if row.iso_alpha in meta:
        meta[row.iso_alpha]['continent']=row.continent
for k,v in list(meta.items()):
    c=pycountry.countries.get(alpha_3=k)
    if c: v['geo_id']=int(c.numeric)
    else:v['geo_id']=None
for c in pycountry.countries:
    if c.alpha_3 not in meta:meta[c.alpha_3]={'name':c.name,'lat':None,'lon':None,'continent':'','geo_id':int(c.numeric)}
# Targeted missing or legacy codes in base reference
for k,v in {'MYS':(2.5,112.5,'Asia'),'SGP':(1.35,103.8,'Asia'),'BRN':(4.5,114.7,'Asia'),'TLS':(-8.8,125.8,'Asia'),'KOR':(36.3,127.8,'Asia'),'TWN':(23.7,121,'Asia'),'USA':(38,-97,'North America'),'CHN':(35,104,'Asia'),'RUS':(61,99,'Europe'),'GBR':(54,-3,'Europe'),'VNM':(16.1,107.8,'Asia')}.items():
    if k in meta:meta[k].update({'lat':v[0],'lon':v[1],'continent':v[2]})
(P/'data'/'country_meta.json').write_text(json.dumps(meta,ensure_ascii=False,indent=2))
base={'$schema':'https://vega.github.io/schema/vega-lite/v5.json','background':None,'config':{'font':'Inter, Arial, sans-serif','view':{'stroke':None},'axis':{'domain':False,'gridColor':'#e6ebef','gridOpacity':0.8,'labelColor':'#50606e','titleColor':'#334450','tickColor':'#d6dee4','labelFontSize':11,'titleFontSize':12,'titlePadding':12},'legend':{'labelColor':'#445563','titleColor':'#334450','labelFontSize':11,'titleFontSize':11},'title':{'color':'#182d3a','fontSize':15},'range':{'category':['#24566b','#77a9ac','#b49a76','#6390b0','#78917c','#c0a1a0','#5f7485']}}}
def save(name,**kw):
  spec={**base,**kw}
  (P/'specs'/f'{name}.json').write_text(json.dumps(spec,indent=2,ensure_ascii=False)+'\n')
# 01 world choropleth, lookup values injected by app
save('01_internet_choropleth',width='container',height=390,projection={'type':'equalEarth'},data={'url':'https://cdn.jsdelivr.net/npm/vega-datasets@2/data/world-110m.json','format':{'type':'topojson','feature':'countries'}},transform=[{'lookup':'id','from':{'data':{'values':[]},'key':'geo_id','fields':['metric','country','year']}}],mark={'type':'geoshape','stroke':'#fff','strokeWidth':0.5},encoding={'color':{'field':'metric','type':'quantitative','scale':{'domain':[0,100],'scheme':'tealblues'},'legend':{'title':'People using internet (%)','orient':'bottom','gradientLength':260}},'tooltip':[{'field':'country','type':'nominal','title':'Country'},{'field':'metric','type':'quantitative','title':'Internet users (%)','format':'.1f'},{'field':'year','type':'ordinal','title':'Year'}]})
# 02 graduated circle map, world basemap + dynamic centroids
