# 05 matrix
save('05_asean_heatmap',width='container',height=285,data={'values':[]},mark={'type':'rect','cornerRadius':2,'stroke':'#fff','strokeWidth':2},encoding={'y':{'field':'country','type':'ordinal','title':None,'sort':['Singapore','Malaysia','Thailand','Vietnam','Indonesia','Philippines','Cambodia','Laos','Myanmar','Brunei','Timor-Leste']},'x':{'field':'year','type':'ordinal','title':None},'color':{'field':'metric','type':'quantitative','scale':{'domain':[0,100],'scheme':'tealblues'},'legend':{'orient':'bottom','title':'Internet access (%)'}},'tooltip':[{'field':'country'},{'field':'year'},{'field':'metric','title':'Internet users (%)','format':'.1f'}]})
