save('06_subscription_violin',width='container',height=328,data={'values':[]},mark={'type':'area','orient':'vertical','opacity':0.81},encoding={'x':{'field':'value','type':'quantitative','title':'Subscriptions per 100 people (2024)','scale':{'domain':[0,210]}},'y':{'field':'bottom','type':'quantitative','title':None,'scale':{'domain':[-0.8,5.8]},'axis':{'values':[0,1,2,3,4,5],'labelExpr':"['Africa','Asia','Europe','N. America','S. America','Oceania'][datum.value]",'grid':False}},'y2':{'field':'top'},'color':{'field':'continent','type':'nominal','legend':None,'scale':{'domain':['Africa','Asia','Europe','North America','South America','Oceania'],'range':['#78917c','#24566b','#77a9ac','#b49a76','#6390b0','#c0a1a0']}},'tooltip':[{'field':'continent','title':'Region'},{'field':'value','title':'Subscriptions / 100','format':'.0f'}]})
