save('07_asean_bump',width='container',height=340,data={'values':[]},mark={'type':'line','point':{'filled':True,'size':45},'strokeWidth':2.5},encoding={'x':{'field':'year','type':'ordinal','title':'Year','axis':{'labelAngle':0}},'y':{'field':'rank','type':'quantitative','title':'Position among compared countries','scale':{'domain':[11.5,0.5]},'axis':{'values':[1,3,5,7,9,11]}},'color':{'field':'country','type':'nominal','legend':{'orient':'bottom','columns':5},'scale':{'domain':['Malaysia','Singapore','Thailand','Indonesia','Vietnam','Philippines','Cambodia','Laos','Myanmar','Brunei','Timor-Leste'],'range':['#d27f53','#244f68','#82aba8','#a8b7b8','#9fae87','#8c99bb','#bea5a2','#b1a18a','#90aeb6','#76938c','#cbbdad']}},'detail':{'field':'country'},'tooltip':[{'field':'country'},{'field':'year'},{'field':'rank','title':'Rank'},{'field':'metric','title':'Internet users (%)','format':'.1f'}]})
